package com.example.ejercicio_1_permisosimport android.Manifestimport android.content.Intentimport android.net.Uriimport android.os.Bundleimport android.provider.Settingsimport androidx.activity.ComponentActivityimport androidx.activity.compose.setContentimport androidx.compose.foundation.layout.*import androidx.compose.material3.Buttonimport androidx.compose.material3.Textimport androidx.compose.runtime.*import androidx.compose.ui.Modifierimport androidx.compose.ui.platform.LocalContextimport androidx.compose.ui.unit.dpimport androidx.lifecycle.ViewModelimport androidx.lifecycle.viewmodel.compose.viewModelimport com.google.accompanist.permissions.ExperimentalPermissionsApiimport com.google.accompanist.permissions.isGrantedimport com.google.accompanist.permissions.rememberPermissionStateimport com.google.accompanist.permissions.shouldShowRationaledata class EstadoPantalla(    val textoInformativo: String = "Presiona los botones para pedir permisos",    val mostrarBotonAjustes: Boolean = false)class VistaModeloPermisos : ViewModel() {    var estado by mutableStateOf(EstadoPantalla())        private set    fun cambiarMensaje(nuevoMensaje: String) {        estado = estado.copy(textoInformativo = nuevoMensaje)    }    fun cambiarVisibilidadBoton(visible: Boolean) {        estado = estado.copy(mostrarBotonAjustes = visible)    }}class MainActivity : ComponentActivity() {    override fun onCreate(savedInstanceState: Bundle?) {        super.onCreate(savedInstanceState)        setContent {            PantallaPrincipal()        }    }}@OptIn(ExperimentalPermissionsApi::class)@Composablefun PantallaPrincipal(modelo: VistaModeloPermisos = viewModel()) {    val contexto = LocalContext.current    var haSolicitado by remember { mutableStateOf(false) }    val permisoAudio = rememberPermissionState(Manifest.permission.RECORD_AUDIO) { fueOtorgado ->        val msg = if (fueOtorgado) "Audio: Aceptado" else "Audio: Rechazado"        modelo.cambiarMensaje(msg)    }    val permisoCalendario = rememberPermissionState(Manifest.permission.READ_CALENDAR) { fueOtorgado ->        val msg = if (fueOtorgado) "Calendario: Aceptado" else "Calendario: Rechazado"        modelo.cambiarMensaje(msg)    }    LaunchedEffect(permisoAudio.status, permisoCalendario.status, haSolicitado) {        if (haSolicitado) {            val audioBloqueado = !permisoAudio.status.isGranted && !permisoAudio.status.shouldShowRationale            val calendaBloqueado = !permisoCalendario.status.isGranted && !permisoCalendario.status.shouldShowRationale            if (audioBloqueado || calendaBloqueado) {                modelo.cambiarVisibilidadBoton(true)                modelo.cambiarMensaje("Permiso bloqueado permanentemente. Ve a ajustes.")            } else {                modelo.cambiarVisibilidadBoton(false)            }        }    }    Column(modifier = Modifier.padding(20.dp)) {        Text(text = modelo.estado.textoInformativo)        Spacer(modifier = Modifier.height(20.dp))        Row {            Button(onClick = {                haSolicitado = true                permisoAudio.launchPermissionRequest()            }) {                Text("Pedir Audio")            }            Spacer(modifier = Modifier.width(10.dp))            Button(onClick = {                haSolicitado = true                permisoCalendario.launchPermissionRequest()            }) {                Text("Pedir Calendario")            }        }        if (modelo.estado.mostrarBotonAjustes) {            Spacer(modifier = Modifier.height(20.dp))            Button(onClick = {                val intent = Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply {                    data = Uri.fromParts("package", contexto.packageName, null)                }                contexto.startActivity(intent)            }) {                Text("Ir a Ajustes")            }        }    }}